import{_ as n,o as s,c as e,a5 as i}from"./chunks/framework.DJo0M80U.js";const h=JSON.parse('{"title":"92. Building a Command-Line Tool","description":"The Little Book of C — 92. Building a Command-Line Tool","frontmatter":{"title":"92. Building a Command-Line Tool","date":"2026-07-04","categories":["C 教程"],"tags":["C","Little Book of C","Building Real Projects"],"description":"The Little Book of C — 92. Building a Command-Line Tool","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","section":92,"sidebarWeight":92,"lang":"en-US","alternateEn":"/posts/c教程/en-US/10-Building Real Projects/092-Building a Command-Line Tool","alternateZh":"/posts/c教程/zh-CN/10-真实项目/092-Building a Command-Line Tool"},"headers":[],"relativePath":"posts/c教程/en-US/10-Building Real Projects/092-Building a Command-Line Tool.md","filePath":"posts/c教程/en-US/10-Building Real Projects/092-Building a Command-Line Tool.md","lastUpdated":1790163617000}'),t={name:"posts/c教程/en-US/10-Building Real Projects/092-Building a Command-Line Tool.md"};function l(p,a,o,c,r,d){return s(),e("div",null,[...a[0]||(a[0]=[i(`<p>[中文版本](/posts/c教程/zh-CN/10-真实项目/092-Building a Command-Line Tool)</p><p>Command-line tools are where most C programmers begin building real software. They are fast, portable, and integrate naturally with Unix-like environments. In this section, you’ll build a small, self-contained CLI tool that processes input arguments, reads files, and outputs results, the same pattern used by tools like<code>grep</code>,<code>cat</code>, and<code>wc</code>.</p><h4 id="step-1-the-goal" tabindex="-1">Step 1. The Goal <a class="header-anchor" href="#step-1-the-goal" aria-label="Permalink to &quot;Step 1. The Goal&quot;">​</a></h4><p>We’ll build a simple command-line tool called linestat that:</p><ul><li>Counts lines, words, and characters in a text file (like a mini<code>wc</code>).</li><li>Takes input from a file or standard input.</li><li>Accepts flags like<code>-l</code>,<code>-w</code>,<code>-c</code>.</li><li>Uses clean error handling and modular functions.</li></ul><h4 id="step-2-project-layout" tabindex="-1">Step 2. Project Layout <a class="header-anchor" href="#step-2-project-layout" aria-label="Permalink to &quot;Step 2. Project Layout&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>linestat/</span></span>
<span class="line"><span> ├── linestat.c</span></span>
<span class="line"><span> ├── Makefile</span></span>
<span class="line"><span> └── README.md</span></span></code></pre></div><h4 id="step-3-core-concepts" tabindex="-1">Step 3. Core Concepts <a class="header-anchor" href="#step-3-core-concepts" aria-label="Permalink to &quot;Step 3. Core Concepts&quot;">​</a></h4><p>Command-line programs follow a few timeless patterns:</p><ol><li>Read arguments with<code>argc</code> and<code>argv</code>.</li><li>Validate inputs before processing.</li><li>Open files safely with<code>fopen</code> or use<code>stdin</code>.</li><li>Process data line-by-line.</li><li>Report results clearly and consistently.</li></ol><h4 id="step-4-tiny-code-linestat-c" tabindex="-1">Step 4. Tiny Code: linestat.c <a class="header-anchor" href="#step-4-tiny-code-linestat-c" aria-label="Permalink to &quot;Step 4. Tiny Code: linestat.c&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span>#include &lt;string.h&gt;</span></span>
<span class="line"><span>static void print_usage(const char *prog) {</span></span>
<span class="line"><span>    printf(&quot;Usage: %s [-l] [-w] [-c] [file]\\n&quot;, prog);</span></span>
<span class="line"><span>    printf(&quot;Options:\\n&quot;);</span></span>
<span class="line"><span>    printf(&quot;  -l   count lines\\n&quot;);</span></span>
<span class="line"><span>    printf(&quot;  -w   count words\\n&quot;);</span></span>
<span class="line"><span>    printf(&quot;  -c   count characters\\n&quot;);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>int main(int argc, char *argv[]) {</span></span>
<span class="line"><span>    int count_lines = 0, count_words = 0, count_chars = 0;</span></span>
<span class="line"><span>    const char *filename = NULL;</span></span>
<span class="line"><span>    // Parse arguments</span></span>
<span class="line"><span>    for (int i = 1; i &lt; argc; i++) {</span></span>
<span class="line"><span>        if (strcmp(argv[i], &quot;-l&quot;) == 0) count_lines = 1;</span></span>
<span class="line"><span>        else if (strcmp(argv[i], &quot;-w&quot;) == 0) count_words = 1;</span></span>
<span class="line"><span>        else if (strcmp(argv[i], &quot;-c&quot;) == 0) count_chars = 1;</span></span>
<span class="line"><span>        else if (argv[i][0] != &#39;-&#39;) filename = argv[i];</span></span>
<span class="line"><span>        else {</span></span>
<span class="line"><span>            print_usage(argv[0]);</span></span>
<span class="line"><span>            return 1;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    FILE *fp = filename ? fopen(filename, &quot;r&quot;) : stdin;</span></span>
<span class="line"><span>    if (!fp) {</span></span>
<span class="line"><span>        perror(&quot;Error opening file&quot;);</span></span>
<span class="line"><span>        return 1;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    long lines = 0, words = 0, chars = 0;</span></span>
<span class="line"><span>    int in_word = 0;</span></span>
<span class="line"><span>    int ch;</span></span>
<span class="line"><span>    while ((ch = fgetc(fp)) != EOF) {</span></span>
<span class="line"><span>        chars++;</span></span>
<span class="line"><span>        if (ch == &#39;\\n&#39;) lines++;</span></span>
<span class="line"><span>        if (ch == &#39; &#39; || ch == &#39;\\n&#39; || ch == &#39;\\t&#39;) in_word = 0;</span></span>
<span class="line"><span>        else if (!in_word) { words++; in_word = 1; }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    fclose(fp);</span></span>
<span class="line"><span>    if (!count_lines &amp;&amp; !count_words &amp;&amp; !count_chars) {</span></span>
<span class="line"><span>        count_lines = count_words = count_chars = 1; // Default all</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>    if (count_lines) printf(&quot;Lines: %ld\\n&quot;, lines);</span></span>
<span class="line"><span>    if (count_words) printf(&quot;Words: %ld\\n&quot;, words);</span></span>
<span class="line"><span>    if (count_chars) printf(&quot;Chars: %ld\\n&quot;, chars);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><h4 id="step-5-build-and-run" tabindex="-1">Step 5. Build and Run <a class="header-anchor" href="#step-5-build-and-run" aria-label="Permalink to &quot;Step 5. Build and Run&quot;">​</a></h4><p>Makefile</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CC = gcc</span></span>
<span class="line"><span>CFLAGS = -std=c23 -O2 -Wall -Wextra</span></span>
<span class="line"><span>linestat: linestat.c</span></span>
<span class="line"><span>    $(CC) $(CFLAGS) linestat.c -o linestat</span></span>
<span class="line"><span>clean:</span></span>
<span class="line"><span>    rm -f linestat</span></span></code></pre></div><p>Build it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make</span></span></code></pre></div><p>Run it:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./linestat -l -w -c example.txt</span></span></code></pre></div><p>Or from a pipeline:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cat example.txt | ./linestat -w</span></span></code></pre></div><p>Example output:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Lines: 12</span></span>
<span class="line"><span>Words: 85</span></span>
<span class="line"><span>Chars: 430</span></span></code></pre></div><h4 id="step-6-breaking-down-the-code" tabindex="-1">Step 6. Breaking Down the Code <a class="header-anchor" href="#step-6-breaking-down-the-code" aria-label="Permalink to &quot;Step 6. Breaking Down the Code&quot;">​</a></h4><ul><li>Argument Parsing: Loops through<code>argv</code> to detect flags.</li><li>Input Handling: Reads from<code>stdin</code> when no file is given.</li><li>Counting Logic: Tracks transitions between spaces and characters to count words.</li><li>Graceful Exit: Uses<code>fclose</code> and<code>perror</code> for error reporting.</li><li>Default Behavior: When no flags are passed, all counts are printed.</li></ul><h4 id="step-7-making-it-more-robust" tabindex="-1">Step 7. Making It More Robust <a class="header-anchor" href="#step-7-making-it-more-robust" aria-label="Permalink to &quot;Step 7. Making It More Robust&quot;">​</a></h4><p>You can extend this program easily:</p><p>Add<code>-q</code> for quiet mode (only print totals).</p><p>Add<code>--help</code> for extended usage info.</p><p>Use<code>getline()</code> for reading full lines (C POSIX).</p><p>Print counts side by side in a single line:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12  85  430  example.txt</span></span></code></pre></div><h4 id="step-8-cross-platform-considerations" tabindex="-1">Step 8. Cross-Platform Considerations <a class="header-anchor" href="#step-8-cross-platform-considerations" aria-label="Permalink to &quot;Step 8. Cross-Platform Considerations&quot;">​</a></h4><ul><li>Use<code>#ifdef _WIN32</code> to handle file paths and newline differences.</li><li>Always open files in text mode:<code>fopen(filename, &quot;r&quot;)</code>.</li><li>Use<code>size_t</code> instead of<code>long</code> for portability.</li></ul><h4 id="step-9-why-it-matters" tabindex="-1">Step 9. Why It Matters <a class="header-anchor" href="#step-9-why-it-matters" aria-label="Permalink to &quot;Step 9. Why It Matters&quot;">​</a></h4><p>Writing a CLI teaches key systems skills:</p><ul><li>Argument parsing and I/O</li><li>File handling and error checking</li><li>Performance thinking (streaming, buffering)</li><li>Modular design for future features</li></ul><p>Every developer who writes in C eventually writes a CLI, it’s how tools like Git, Curl, and GCC were born.</p><h4 id="step-10-try-it-yourself" tabindex="-1">Step 10. Try It Yourself <a class="header-anchor" href="#step-10-try-it-yourself" aria-label="Permalink to &quot;Step 10. Try It Yourself&quot;">​</a></h4><ol><li>Add a<code>-v</code> flag that shows program version.</li><li>Support reading multiple files.</li><li>Add timing (use<code>clock()</code> to measure runtime).</li><li>Print totals across all files.</li><li>Integrate your simplemath library to compute average words per line.</li></ol><p>Next, you’ll move to 93. Tiny HTTP Server (Sockets and Threads), where your command-line skills evolve into network programming: accepting connections, handling requests, and serving content in pure C.</p>`,41)])])}const g=n(t,[["render",l]]);export{h as __pageData,g as default};
